def parse_amounts(df):
    def clean_and_parse(amount):
        if amount == "":
            return None
        amount = amount.replace("$", "").replace(",", "")
        try:
            return float(amount)
        except ValueError:
            return None

    df["Amount"] = [clean_and_parse(a) for a in df["Amount"]]
    df["Amount"] = df["Amount"].astype(float)
    return df

